#include <bits/stdc++.h>
using namespace std;

struct dor {
    int sg;
    bool sgl, sgr, fl;
    dor *l, *r;

    dor() : sg(0), sgl(false), sgr(false), fl(false), l(nullptr), r(nullptr) {}

    void pump() {
        sg = 0;
        sgl = sgr = false;

        if (l) {
            sg += l->sg;
            sgl = l->sgl;
        }
        if (r) {
            sg += r->sg;
            sgr = r->sgr;
        }
        if (l && r && l->sgr && r->sgl)
            --sg;
    }

    void fll() {
        sg = 1;
        fl = sgl = sgr = true;
    }
};

const int M = 1000000000;
int n, a, b;
dor *root = nullptr;

void upd(int l, int r, int sl, int sr, dor *&t) {
    if (l > sr || r < sl)
        return;

    if (!t)
        t = new dor();

    if (t->fl)
        return;

    if (sl <= l && r <= sr) {
        t->fll();
        return;
    }

    int mid = l + (r - l) / 2;

    if (sl <= mid)
        upd(l, mid, sl, sr, t->l);
    if (sr > mid)
        upd(mid + 1, r, sl, sr, t->r);

    t->pump();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        cin >> a >> b;
        if (a < b)
            upd(1, M, a, b - 1, root);
        cout << (root ? root->sg : 0) << ' ';
    }

    return 0;
}

