int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    map<long long, long long> segments;

    while (n--) {
        long long a, b;
        cin >> a >> b;

        long long left = a;
        long long right = b - 1;

        if (left <= right) {
            auto it = segments.lower_bound(left);

            if (it != segments.begin()) {
                auto previous = prev(it);
                if (previous->second + 1 >= left)
                    it = previous;
            }

            while (it != segments.end() && it->first <= right + 1) {
                if (it->second + 1 < left) {
                    ++it;
                    continue;
                }

                left = min(left, it->first);
                right = max(right, it->second);
                it = segments.erase(it);
            }

            segments[left] = right;
        }

        cout << segments.size() << ' ';
    }

    return 0;
}

